async function h(){try{const d="koalastuff_github_repos";let r=null;const u=localStorage.getItem(d);if(u){const t=JSON.parse(u);Date.now()-t.timestamp<360*60*1e3&&(r=t.data)}if(!r){const t=await fetch("https://api.github.com/users/Shik3i/repos?sort=updated&per_page=100");if(!t.ok)return;r=await t.json(),localStorage.setItem(d,JSON.stringify({timestamp:Date.now(),data:r}))}const o=new Map;r.forEach(t=>{o.set(t.full_name.toLowerCase(),new Date(t.pushed_at||t.updated_at))});const n=document.getElementById("projects-tracker-rows");if(n){const t=Array.from(n.children);t.sort((s,c)=>{const e=s.querySelector(".github-last-updated"),a=c.querySelector(".github-last-updated"),i=e?e.getAttribute("data-github-repo")?.toLowerCase():null,l=a?a.getAttribute("data-github-repo")?.toLowerCase():null,p=i&&o.has(i)?o.get(i).getTime():0;return(l&&o.has(l)?o.get(l).getTime():0)-p}),t.forEach(s=>n.appendChild(s))}document.querySelectorAll(".github-last-updated").forEach(t=>{const s=t.getAttribute("data-github-repo");if(!s)return;const c=o.get(s.toLowerCase());if(c){const e=Math.floor((Date.now()-c.getTime())/864e5);let a="";e===0?a="Updated today":e===1?a="Updated yesterday":e<30?a=`Updated ${e}d ago`:e<365?a=`Updated ${Math.floor(e/30)}mo ago`:a=`Updated ${Math.floor(e/365)}y ago`,t.innerHTML=`<span class="update-dot"></span>${a}`,t.classList.add("has-fresh-data")}})}catch(d){console.error("Failed to fetch github data",d)}}document.addEventListener("astro:page-load",h);
